/// <summary>
/// Triggering the SO confirmation framework to run the credit check flow.
/// </summary>
/// <param name = "_salesTable">SalesTable reference</param>
public static void METSOProformaPosting(SalesTable _salesTable)
{
    SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);

    salesFormLetter.update(_salesTable, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), SalesUpdate::All, AccountOrder::None, NoYes::Yes, NoYes::No, NoYes::No);

    infolog.cut(); // cutting off all standard info because we are using SO confirmation framework to trigger the cred management, so related info may confuse user. 

    _salesTable.reread();

    if (_salesTable.METCreditCheckSalesOrder)
    {
        info(strFmt("@MET:SOCreditSent", _salesTable.SalesId));
    }
}

/// <summary>
/// Delete the exisiting credit hold list
/// </summary>
/// <param name = "_salesTable">Sales table reference</param>
public static void METDeletePreviousCreditHoldList(SalesTable _salesTable)
{
    CredManTable    credManTableDel;
    CredManTrans    credManTrans;
    SalesLine       salesLine;

    if (_salesTable.CredManId)
    {
        ttsbegin;
        _salesTable.selectForUpdate(true);
        _salesTable.CredManId = '';
        _salesTable.update();
        ttscommit;
    }

    delete_from credManTableDel
        where credManTableDel.SalesId == _salesTable.SalesId;

    delete_from credManTrans
        exists join salesLine
            where credManTrans.InventTransId == salesLine.InventTransId
                && salesLine.SalesId == _salesTable.SalesId;
}
